import app from "flarum/admin/app";
import Component from "flarum/common/Component";
import extractText from "flarum/common/utils/extractText";
import DocumentTypesState from "../states/DocumentTypesState";
const trans = key => app.translator.trans(`ramon-verified.admin.${key}`);

/**
 * Editor for the configurable list of accepted document types.
 *
 * Each row is an `{ id, label }` pair (id used by the backend, label shown
 * to users). Saves are debounced via the bound state.
 */
export default class DocumentTypesEditor extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.types = new DocumentTypesState();
  }
  view() {
    const rows = this.types.types;
    return m("div", {
      className: "VerifiedAdmin-row VerifiedAdmin-types"
    }, m("div", {
      className: "VerifiedAdmin-types-header"
    }, m("span", {
      className: "VerifiedAdmin-types-headerId"
    }, trans("settings.document_type_id_header")), m("span", {
      className: "VerifiedAdmin-types-headerLabel"
    }, trans("settings.document_type_label_header"))), m("div", {
      className: "VerifiedAdmin-types-list"
    }, rows.length === 0 ? m("p", {
      className: "VerifiedAdmin-types-empty helpText"
    }, trans("settings.document_types_empty")) : rows.map((row, idx) => m("div", {
      className: "VerifiedAdmin-types-row",
      key: idx
    }, m("input", {
      type: "text",
      className: "FormControl VerifiedAdmin-types-input VerifiedAdmin-types-id",
      value: row.id,
      placeholder: "rg",
      spellcheck: "false",
      autocomplete: "off",
      oninput: e => this.types.update(idx, "id", e.target.value)
    }), m("input", {
      type: "text",
      className: "FormControl VerifiedAdmin-types-input VerifiedAdmin-types-label",
      value: row.label,
      placeholder: extractText(trans("settings.document_type_label_placeholder")),
      oninput: e => this.types.update(idx, "label", e.target.value)
    }), m("button", {
      type: "button",
      className: "VerifiedAdmin-types-remove",
      onclick: () => this.types.remove(idx),
      "aria-label": extractText(trans("settings.document_type_remove")),
      title: extractText(trans("settings.document_type_remove"))
    }, m("i", {
      className: "icon fas fa-times"
    }))))), m("button", {
      type: "button",
      className: "VerifiedAdmin-types-add",
      onclick: () => this.types.add()
    }, m("i", {
      className: "icon fas fa-plus"
    }), trans("settings.document_type_add")));
  }
}
flarum.reg.add('ramon-verified', 'admin/components/DocumentTypesEditor', DocumentTypesEditor);